def transform(grid):
    import numpy as np
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    tracks = [r for r in range(H) if int((g[r] == 8).sum()) > W // 2]

    # 1. rungs: horizontal 7-bars become vertical 6-bars joining adjacent tracks
    rungs = {}
    for r in range(H):
        c = 0
        while c < W:
            if g[r, c] != 7:
                c += 1
                continue
            start = c
            while c < W and g[r, c] == 7:
                c += 1
            middle = (start + c - 1) // 2
            out[r, start:c] = 8
            out[max(r-1, 0):min(r+2, H), middle] = 6
            if 0 < r < H - 1:
                rungs.setdefault(r-1, []).append((middle, r+1))
                rungs.setdefault(r+1, []).append((middle, r-1))
    emit(out, 'Turn every horizontal orange rung into a vertical magenta connector between the tracks above and below.')

    out[out == 3] = 8
    emit(out, 'Lift all green markers off the track ends; they will be redistributed along the ladder paths.')

    def bounds(row, column):
        left = right = column
        while left > 0 and g[row, left-1] != 0:
            left -= 1
        while right + 1 < W and g[row, right+1] != 0:
            right += 1
        return left, right

    endpoints = set()
    for row in tracks:
        for column in range(W):
            if g[row, column] == 0:
                continue
            left, right = bounds(row, column)
            if column == left or column == right:
                endpoints.add((row, column))

    paths = set()
    for sr, sc in sorted(endpoints):
        left, right = bounds(sr, sc)
        direction = 1 if sc == left else -1
        row, column = sr, sc
        first = True
        visited = set()
        while True:
            state = (row, column, direction, first)
            if state in visited:
                break
            visited.add(state)
            left, right = bounds(row, column)
            cands = [(x, other) for x, other in rungs.get(row, [])
                     if left <= x <= right and
                     ((x - column) * direction > 0 or (first and x == column))]
            if not cands:
                column = right if direction > 0 else left
                break
            column, row = min(cands, key=lambda it: abs(it[0] - column))
            direction = -direction   # cross the rung and turn back
            first = False
        paths.add(tuple(sorted(((sr, sc), (row, column)))))

    for a, b in sorted(paths):
        count = int(g[a] == 3) + int(g[b] == 3)
        if not count:
            continue
        if a[0] == b[0]:
            for e in (a, b):
                if g[e] == 3:
                    out[e] = 3
            emit(out, f'Path {a}-{b} ends on the same track: its markers stay in place.')
        else:
            row, column = b
            left, right = bounds(row, column)
            direction = 1 if column == left else -1
            for k in range(count):
                x = column + direction * k
                if 0 <= x < W:
                    out[row, x] = 3
            emit(out, f'Path {a}-{b}: gather its {count} green marker(s) at the lower endpoint, stacked inward.')

    emit(out, 'All rungs rotated and every green marker placed at its path destination.')
    return out
